def transform(g):
    g=np.array(g); n=g.shape[0]
    out=np.zeros_like(g)
    for i in range(n):
        for j in range(n):
            cands=[g[i,j],g[j,i]]
            for a in (i,31-i):
                for b in (j,31-j):
                    cands += [g[a,b],g[b,a]]
            vals=[c for c in cands if 0<=c<6 or c>6]
            out[i,j]=vals[0]
    return out
